            assertThat(calculadora.calcular(pedido)).isEqualTo(resumo("399.80", "50.00", "18.00", 0,
                    "8.00", "3.49", "379.29", 1, "379.29", "0.00", false));
        }

        @Test
        void exemplo4_retiradaComLeve3Pague2NoCartaoEm3vezesPrataSul() {
