            recusa(pedido(List.of(new ItemRequest("X", new BigDecimal("10.00"), 1, null)), "RETIRADA_LOJA",
                    null, "PIX", 1, "BRONZE", "SUDESTE"), CodigoErro.PEDIDO_INVALIDO);
        }

